var builder = WebApplication.CreateBuilder(args);

builder.Services.AddCors(options =>
{
    options.AddPolicy("AdminPolicy", policy =>
    {
        policy
            .WithOrigins("https://admin.example.com")
            .AllowAnyHeader()
            .AllowAnyMethod()
            .AllowCredentials();
    });
});

builder.Services.AddControllersWithViews();

var app = builder.Build();
app.UseHttpsRedirection();
app.UseStaticFiles();
app.UseRouting();
app.UseCors("AdminPolicy");
app.UseAuthorization();
app.MapControllerRoute(
    name: "default",
    pattern: "{controller=Home}/{action=Index}/{id?}");
app.Run();

using Microsoft.AspNetCore.Cors;

[ApiController]
[Route("api/[controller]")]
public class ReportsController : ControllerBase
{
    [HttpGet("public")]
    public IActionResult GetPublicReport()
    {
        return Ok("Anyone can access this report.");
    }

    [HttpGet("admin")]
    [EnableCors("AdminPolicy")]
    public IActionResult GetAdminReport()
    {
        return Ok("Only the admin frontend can access this report.");
    }
}

using Microsoft.AspNetCore.Cors;

[EnableCors("AdminPolicy")]
[ApiController]
[Route("api/[controller]")]
public class AdminController : ControllerBase
{
    [HttpGet("users")]
    public IActionResult GetUsers()
    {
        return Ok(new[] { "Alice", "Bob" });
    }

    [HttpPost("users")]
    public IActionResult CreateUser([FromBody] User user)
    {
        return CreatedAtAction(nameof(GetUsers), user);
    }
}

using Microsoft.AspNetCore.Cors;

[EnableCors("AdminPolicy")]
[ApiController]
[Route("api/[controller]")]
public class InternalController : ControllerBase
{
    [HttpGet("public")]
    public IActionResult GetPublic()
    {
        return Ok("This endpoint allows CORS.");
    }

    [DisableCors]
    [HttpGet("secret")]
    public IActionResult GetSecret()
    {
        // CORS headers are removed from this response
        return Ok("This endpoint blocks cross-origin requests.");
    }
}
